using System;using System.Linq;using System.Threading;using System.Threading.Tasks;using System.Windows;using System.Windows.Controls;using System.Windows.Media;using System.Windows.Threading;
namespace Dafeiyu.Tests {public static class LocalImportUiTests {
[STAThread]public static int Main(){var app=new Application{ShutdownMode=ShutdownMode.OnExplicitShutdown};int result=1;var host=new Window{Width=300,Height=150};host.Loaded+=async delegate{try{var timer=new DispatcherTimer{Interval=TimeSpan.FromMilliseconds(100)};timer.Tick+=delegate{var progress=app.Windows.OfType<LocalCompanionImportWindow>().FirstOrDefault();if(progress==null)return;timer.Stop();Find(progress).Single(b=>b.Name=="CancelCompanionImport").RaiseEvent(new RoutedEventArgs(Button.ClickEvent));};timer.Start();bool cancelled=false;try{await LocalCompanionImportWindow.RunAsync<int>(host,token=>{token.WaitHandle.WaitOne(5000);token.ThrowIfCancellationRequested();return 1;});}catch(OperationCanceledException){cancelled=true;}if(!cancelled||app.Windows.OfType<LocalCompanionImportWindow>().Any())throw new Exception("cancel must close progress after worker acknowledgement");Console.WriteLine("PASS native cancellable import dialog");result=0;}catch(Exception ex){Console.Error.WriteLine(ex);}finally{host.Close();app.Shutdown();}};host.Show();app.Run();return result;}
static System.Collections.Generic.IEnumerable<Button> Find(DependencyObject root){if(root is Button)yield return(Button)root;for(int i=0;i<VisualTreeHelper.GetChildrenCount(root);i++)foreach(var b in Find(VisualTreeHelper.GetChild(root,i)))yield return b;}
}}
